def windowKSmallestSums(nums, w, k):
    n = len(nums)
    order = sorted(range(n), key=lambda i: (nums[i], i))
    rank = [0] * n
    for j, i in enumerate(order):
        rank[i] = j + 1
    cnt = [0] * (n + 1)
    sm = [0] * (n + 1)
    top = 1
    while top * 2 <= n:
        top *= 2

    def update(i, dc, dv):
        while i <= n:
            cnt[i] += dc
            sm[i] += dv
            i += i & -i

    out = []
    for i in range(n):
        update(rank[i], 1, nums[i])
        if i >= w:
            update(rank[i - w], -1, -nums[i - w])
        if i >= w - 1:
            pos, rem, total, step = 0, k, 0, top
            while step:
                nxt = pos + step
                if nxt <= n and cnt[nxt] <= rem:
                    pos = nxt
                    rem -= cnt[nxt]
                    total += sm[nxt]
                step >>= 1
            out.append(total)
    return out
